import XCTest
@testable import PocketDJ

/// Pocket Wheel Phase 2 — the moment engine (§1.3 / §1.5 / §1.6) on the shared 3-week fixture
/// (`Tests/Fixtures/pocket-wheel-history.json`, generated by `apple/scripts/gen-pocket-wheel-fixture.py`)
/// plus hand-built single-play cases for the kernel, decay and run-weight rules.
final class PocketMomentEngineTests: XCTestCase {

    // MARK: - Fixture

    struct Fixture: Decodable {
        struct Song: Decodable { var artist: String; var genre: String?; var bpm: Double?; var year: Int? }
        struct Coll: Decodable { var id: String; var name: String; var songIds: [String] }
        var nowMs: Double
        var tzOffsetMin: Int
        var librarySize: Int
        var songs: [String: Song]
        var collections: [Coll]
        var events: [PlayHistoryStore.PlayEvent]
    }

    static func loadFixture() throws -> Fixture {
        let url = try XCTUnwrap(Bundle(for: Self.self).url(forResource: "pocket-wheel-history", withExtension: "json"))
        return try JSONDecoder().decode(Fixture.self, from: Data(contentsOf: url))
    }

    static func input(_ f: Fixture) -> PocketMomentEngine.Input {
        PocketMomentEngine.Input(
            events: f.events,
            collections: f.collections.map { .init(id: $0.id, name: $0.name, songIds: Set($0.songIds)) },
            songs: f.songs.mapValues { .init(artist: $0.artist, genre: $0.genre, bpm: $0.bpm, year: $0.year) },
            librarySize: f.librarySize, nowMs: f.nowMs)
    }

    private func wheel() throws -> (PocketWheelSnapshot, [PocketMomentKey: PocketMoment]) {
        let snap = PocketMomentEngine.build(Self.input(try Self.loadFixture()))
        return (snap, snap.index())
    }

    private func k(_ dow: Int, _ hour: Int, _ mode: PocketMode) -> PocketMomentKey { .init(hour: hour, dow: dow, mode: mode) }

    // MARK: - Fixture-level behaviour

    func testEachScenarioPaintsItsCellWithItsCollection() throws {
        let (_, m) = try wheel()
        XCTAssertEqual(m[k(2, 8, .carPlay)]?.dominantCollectionId, "pl_potential", "weekday mornings: CarPlay · Potential")
        XCTAssertEqual(m[k(6, 9, .running)]?.dominantCollectionId, "fav_songs",
                       "Saturday run: Browse singles of ♥'d songs → Favorites via membership")
        XCTAssertEqual(m[k(3, 21, .mix)]?.dominantCollectionId, "pkt_late", "evenings: Mix · Late Night (crate origin)")
        XCTAssertEqual(m[k(2, 12, .browse)]?.dominantCollectionId, "pkt_chill", "lunch Browse singles → their collection")
        XCTAssertEqual(m[k(7, 15, .trip)]?.dominantCollectionId, "pls_road", "the A→B trip")
        XCTAssertEqual(m[k(7, 15, .trip)]?.ctx["trip:trp_ab"], 1)
    }

    func testMegaCollectionNeverColoursACell() throws {
        let (snap, _) = try wheel()
        for moment in snap.moments {
            XCTAssertNil(moment.collections["pl_library"], "the whole-library playlist is excluded from the fallback (\(moment.key.token))")
        }
        XCTAssertFalse(snap.dominanceOrder.contains("pl_library"))
    }

    func testDistinctDaysCountDirectCreditOnly() throws {
        let (_, m) = try wheel()
        let tue8 = try XCTUnwrap(m[k(2, 8, .carPlay)])
        XCTAssertEqual(tue8.distinctDays, 3, "three Tuesdays in the 21-day window")
        XCTAssertTrue(tue8.isRecurring)
        let tue7 = try XCTUnwrap(m[k(2, 7, .carPlay)], "smoothing reaches the neighbour hour")
        XCTAssertGreaterThan(tue7.plays, 0)
        XCTAssertEqual(tue7.distinctDays, 0, "…but only direct credit counts days")
        XCTAssertEqual(tue7.directPlays, 0)
        let oneOff = try XCTUnwrap(m[k(4, 3, .browse)])
        XCTAssertEqual(oneOff.distinctDays, 1)
        XCTAssertFalse(oneOff.isRecurring, "the Thursday 3 AM play is a one-off")
    }

    func testSkipsAndGames() throws {
        let (_, m) = try wheel()
        let mon8 = try XCTUnwrap(m[k(1, 8, .carPlay)])
        XCTAssertEqual(mon8.directSkips, 3, "the Monday first-song skip, three Mondays")
        XCTAssertGreaterThan(mon8.skipRate, 0)
        // The game play (Monday 10:00) contributes nothing directly anywhere.
        for mode in PocketMode.allCases {
            XCTAssertEqual(m[k(1, 10, mode)]?.directPlays ?? 0, 0, "games excluded (\(mode))")
        }
    }

    func testDominanceOrderAndWeekShare() throws {
        let (snap, _) = try wheel()
        XCTAssertEqual(snap.dominanceOrder.first, "pl_potential", "the most-played collection seats first")
        XCTAssertTrue(Set(snap.dominanceOrder).isSuperset(of: ["pl_potential", "pkt_late", "fav_songs", "pls_road", "pkt_chill"]))
        let total = snap.weekShare.values.reduce(0, +)
        XCTAssertLessThanOrEqual(total, 1.0 + 1e-9)
        XCTAssertGreaterThan(snap.weekShare["pl_potential"] ?? 0, snap.weekShare["pls_road"] ?? 0)
        XCTAssertEqual(snap.collectionNames["pl_potential"], "Potential")
    }

    func testFeatureAggregates() throws {
        let (_, m) = try wheel()
        let tue8 = try XCTUnwrap(m[k(2, 8, .carPlay)])
        XCTAssertNotNil(tue8.bpmBand, "≥ 3 dated BPMs → a band")
        XCTAssertNotNil(tue8.era)
        XCTAssertEqual(tue8.genres.keys.sorted(), ["hip-hop", "r&b"])
        XCTAssertFalse(tue8.seeds.isEmpty)
        XCTAssertEqual(tue8.collections.values.reduce(0, +), 1, accuracy: 1e-6, "L1-normalised")
    }

    func testDeterministic() throws {
        let a = PocketMomentEngine.build(Self.input(try Self.loadFixture()))
        let b = PocketMomentEngine.build(Self.input(try Self.loadFixture()))
        XCTAssertEqual(a, b)
        // The cache round-trips byte-stable.
        let back = try JSONDecoder().decode(PocketWheelSnapshot.self, from: JSONEncoder().encode(a))
        XCTAssertEqual(back, a)
    }

    // MARK: - Hand-built rules

    /// Tuesday 2026-10-27 08:30 PDT.
    private let tue830 = 1_793_115_000_000.0
    private func play(_ song: String = "s1", at ms: Double, tz: Int? = -420, source: PlayHistoryStore.PlaySource = .playlist,
                      origin: String? = "pl_a", carPlay: Bool? = true, skipped: Bool = false,
                      run: Bool = false) -> PlayHistoryStore.PlayEvent {
        var e = PlayHistoryStore.PlayEvent(id: UUID(), songId: song, playedAt: ms, source: source,
                                           contextId: "set_now_playing", contextName: nil, title: nil, artist: nil,
                                           originInstallId: nil, tzOffsetMin: tz, carPlay: carPlay,
                                           originCollectionId: origin)
        if skipped { e.wasSkipped = true }
        if run { e.pocketRun = PocketRunTag(runId: UUID(), momentKey: "h08|d2|carPlay", rowCollectionId: nil, slot: 1) }
        return e
    }
    private func build(_ events: [PlayHistoryStore.PlayEvent], now: Double? = nil) -> [PocketMomentKey: PocketMoment] {
        PocketMomentEngine.build(.init(events: events, collections: [.init(id: "pl_a", name: "A", songIds: ["s1"])],
                                       nowMs: now ?? tue830)).index()
    }

    func testKernelWeights() {
        let m = build([play(at: tue830)])
        XCTAssertEqual(m[k(2, 8, .carPlay)]?.plays ?? 0, 1, accuracy: 1e-6, "direct")
        XCTAssertEqual(m[k(2, 9, .carPlay)]?.plays ?? 0, 0.5, accuracy: 1e-6, "±1 h")
        XCTAssertEqual(m[k(2, 7, .carPlay)]?.plays ?? 0, 0.5, accuracy: 1e-6)
        XCTAssertEqual(m[k(2, 10, .carPlay)]?.plays ?? 0, 0.15, accuracy: 1e-6, "±2 h")
        XCTAssertEqual(m[k(3, 8, .carPlay)]?.plays ?? 0, 0.25, accuracy: 1e-6, "same day type")
        XCTAssertEqual(m[k(5, 8, .carPlay)]?.plays ?? 0, 0.25, accuracy: 1e-6)
        XCTAssertNil(m[k(6, 8, .carPlay)], "a weekday play never credits the weekend")
        XCTAssertEqual(m[k(2, 8, .trip)]?.plays ?? 0, 0.3, accuracy: 1e-6, "related mode (carPlay ↔ trip)")
        XCTAssertNil(m[k(2, 8, .mix)])
        XCTAssertEqual(m.count, 1 + 4 + 4 + 1)
    }

    func testHourWrapsAcrossTheWeek() {
        // Monday 00:30 PDT credits Sunday 23:00 at ±1 h.
        let mon0030 = tue830 - 32 * 3_600_000
        let m = build([play(at: mon0030)], now: mon0030)
        XCTAssertEqual(m[k(1, 0, .carPlay)]?.directPlays, 1)
        XCTAssertEqual(m[k(7, 23, .carPlay)]?.plays ?? 0, 0.5, accuracy: 1e-6)
        XCTAssertEqual(m[k(7, 22, .carPlay)]?.plays ?? 0, 0.15, accuracy: 1e-6)
    }

    func testDecayHalvesAtFortyFiveDays() {
        let m = build([play(at: tue830 - 45 * 86_400_000 * 1.0 + 0)], now: tue830)
        // 45 days before a Tuesday is a Sunday — find the direct cell.
        let direct = m.values.first { $0.directPlays == 1 }
        XCTAssertEqual(direct?.plays ?? 0, 0.5, accuracy: 1e-6)
    }

    func testRunPlaysHalfWeightRunSkipsFullWeight() {
        let m = build([play(at: tue830, run: true), play("s2", at: tue830 + 60_000, skipped: true, run: true)])
        let cell = m[k(2, 8, .carPlay)]
        XCTAssertEqual(cell?.plays ?? 0, 0.5, accuracy: 1e-6, "a run's own picks count half (feedback-loop guard)")
        XCTAssertEqual(cell?.skips ?? 0, 1, accuracy: 1e-6, "its skips are honest negatives")
    }

    func testLocalHourFollowsEachPlaysOwnZone() {
        // The same instant, recorded in Lisbon (UTC+0) vs Los Angeles (UTC−7).
        let m = build([play("s1", at: tue830, tz: 0), play("s2", at: tue830 + 3_600_000, tz: -420)])
        XCTAssertEqual(m[k(2, 15, .carPlay)]?.directPlays, 1, "15:30Z in UTC+0 → 15:00")
        XCTAssertEqual(m[k(2, 9, .carPlay)]?.directPlays, 1, "16:30Z in UTC−7 → 09:00")
        // A play without an offset uses the most common one.
        let m2 = build([play("s1", at: tue830, tz: -420), play("s2", at: tue830 + 7_200_000, tz: nil)])
        XCTAssertEqual(m2[k(2, 10, .carPlay)]?.directPlays, 1)
    }

    func testMixedCellHasNoDominantCollection() {
        let ids = ["pl_1", "pl_2", "pl_3", "pl_4", "pl_5"]
        let events = ids.enumerated().map { i, id in play("s\(i)", at: tue830 + Double(i) * 60_000, origin: id) }
        let snap = PocketMomentEngine.build(.init(
            events: events, collections: ids.map { .init(id: $0, name: $0, songIds: []) }, nowMs: tue830))
        let cell = snap.index()[k(2, 8, .carPlay)]
        XCTAssertEqual(cell?.collections.count, 5)
        XCTAssertNil(cell?.dominantCollectionId, "no collection ≥ 25 % ⇒ mixed")
    }

    func testFallbackSpreadsOverHardMembershipsAndSkipsMega() {
        let events = [play("s1", at: tue830, source: .browser, origin: nil, carPlay: nil)]
        let colls: [PocketMomentEngine.CollectionInfo] = [
            .init(id: "pkt_a", name: "A", songIds: ["s1"]),
            .init(id: "pkt_b", name: "B", songIds: ["s1"]),
            .init(id: "pl_all", name: "All", songIds: Set((0..<4000).map { "x\($0)" } + ["s1"])),
        ]
        let snap = PocketMomentEngine.build(.init(events: events, collections: colls, librarySize: 10_000, nowMs: tue830))
        let cell = snap.index()[k(2, 8, .browse)]
        XCTAssertEqual(cell?.collections["pkt_a"] ?? 0, 0.5, accuracy: 1e-6)
        XCTAssertEqual(cell?.collections["pkt_b"] ?? 0, 0.5, accuracy: 1e-6)
        XCTAssertNil(cell?.collections["pl_all"], "> 3,000 songs ⇒ mega ⇒ never the fallback")
    }

    func testOriginPrecedence() {
        let input = PocketMomentEngine.Input(
            events: [], collections: [.init(id: "pls_x", name: "X", songIds: []), .init(id: "pkt_y", name: "Y", songIds: [])],
            setlistToPlaylist: ["set_1": "pls_x"], nowMs: tue830)
        let idx = PocketMomentEngine.MembershipIndex(input, onlySongs: [])
        var e = play(at: tue830, origin: nil)
        e.contextId = "set_1"
        XCTAssertEqual(PocketMomentEngine.origin(of: e, input: input, index: idx), "pls_x", "a setlist resolves to its playlist")
        e.originCollectionId = "pkt_y"
        XCTAssertEqual(PocketMomentEngine.origin(of: e, input: input, index: idx), "pkt_y")
        e.pocketRun = PocketRunTag(runId: UUID(), momentKey: "", rowCollectionId: "pls_x", slot: 1)
        XCTAssertEqual(PocketMomentEngine.origin(of: e, input: input, index: idx), "pls_x", "the run row's collection first")
        var single = play(at: tue830, origin: nil)
        single.contextId = "set_now_playing"
        XCTAssertNil(PocketMomentEngine.origin(of: single, input: input, index: idx), "the reserved queue is no collection")
    }
}
